  eq(terra.bandaVolume(1000, 8), { volume: 1000, banda: 80, min: 920, max: 1080 }, "1000 ±8% = ±80");
  eq(terra.bandaVolume(50, 8).min, 46, "min non negativo");
  eq(terra.bandaVolume(100, null), null, "tolleranza assente → null");
