/* ⚠️ SECONDA VOLTA OGGI che una sostituzione a tappeto colpisce un'ancora
   che è sottostringa di altro: stamattina `N.` → `conti.` ha trasformato
   `JSON.` in `JSOconti.`, qui `O.` → `terra.` ha fatto di `PIENO.origine`
   un `PIENterra.origine`. Una sostituzione «meccanica» su un testo è
   meccanica solo finché l'ancora non compare dentro un altro nome. */
const PIENO = { origine: { da: "visore", file: "cava.las", quandoVisore: "2026-07-15T09:12",
  puntiTotali: 4812331, puntiRitaglio: 218004, cella: 0.5, quotaBase: 340.42, areaCoperta: 729,
  ritaglio: { x0: 10, x1: 70, y0: 5, y1: 65, z0: 338, z1: 352 }, georeferenziato: true } };
console.log("\n— La provenienza del volume (tracciabilità del rilievo) —");

/* ⛔ LA PROVA CHE LA SCHEDA INDICA COME PRIMA */
test("senza origine la frase NON sembra una misura, e lo dice", () => {
  const f = terra.descriviOrigine({ volumeM3: 1000 });
  ok(/non è registrata|non risultano/.test(f), "deve dire che non si sa");
  ok(/non è riproducibile/.test(f), "e che il numero non è rifacibile");
  /* l'asserzione giusta non è «non nominare i parametri» — la frase LI NOMINA,
     per dire che non ci sono, ed è esattamente quello che deve fare. È «non
     mostrare NUMERI»: un valore scritto lì dentro sarebbe una misura inventata,
     ed è l'unica cosa che rende una frase d'assenza pericolosa. */
  ok(!/\d/.test(f), "e NON deve contenere nessuna cifra: " + f.slice(0, 90));
});
test("origineDi: assente, malformata o con un `da` inventato ricade su «non registrata»", () => {
  for (const r of [null, {}, { origine: null }, { origine: "visore" }, { origine: { da: "boh" } }])
    eq(terra.origineDi(r).noto, false, "su " + JSON.stringify(r));
  eq(terra.origineDi(PIENO).noto, true, "e con un'origine vera è nota");
  eq(terra.origineDi(PIENO).da, "visore", "col suo `da`");
});
test("dal visore: la frase porta i parametri che rendono il numero rifacibile", () => {
  const f = terra.descriviOrigine(PIENO);
  for (const atteso of ["griglia", "0,50 m", "340,42 m", "729 m²", "218.004", "4.812.331", "cava.las", "15/07/2026"])
    ok(f.includes(atteso), `manca «${atteso}» in: ${f.slice(0, 200)}`);
  ok(/X da 10,00 a 70,00/.test(f), "e il ritaglio");
  ok(!/non risulta registrato/i.test(f), "e non dichiara mancanze che non ci sono");
});
test("⛔ dal visore ma a metà: quello che manca viene DICHIARATO, non saltato", () => {
  const f = terra.descriviOrigine({ origine: { da: "visore", cella: 0.5, puntiRitaglio: 100 } });
  ok(/0,50 m/.test(f), "dice quello che sa");
  ok(/non risulta registrato/i.test(f), "e dichiara quello che non sa");
  ok(/quota di base/.test(f) && /ritaglio/.test(f), "nominando che cosa manca: " + f.slice(-140));
});
test("la nuvola non georeferenziata è un avviso, non un dettaglio", () => {
  const f = terra.descriviOrigine({ origine: { ...PIENO.origine, georeferenziato: false } });
  ok(/NON è georeferenziata/.test(f), "lo deve dire");
  ok(/non in metri cubi/.test(f), "e dire che cosa significa per il numero");
});
test("manuale e csv non fingono di essere un calcolo", () => {
  ok(/inserito a mano/.test(terra.descriviOrigine({ origine: { da: "manuale" } })), "manuale");
  const c = terra.descriviOrigine({ origine: { da: "csv", file: "volumi.csv" } });
  ok(/fuori da questa applicazione/.test(c) && /volumi\.csv/.test(c), "csv: " + c);
});
test("i numeri sono scritti all'italiana e col raggruppamento dichiarato", () => {
  const f = terra.descriviOrigine(PIENO);
  ok(/218\.004/.test(f), "le migliaia col punto");
  ok(/0,50/.test(f), "i decimali con la virgola");
  ok(!/218004/.test(f), "e mai la cifra secca");
});

/* ⛔ IL PARAMETRO CHE NON C'È NON VALE ZERO — censimento del 02/08, tre punti
   dentro questa sola funzione. Il visore scrive `null` sui parametri che non ha
   potuto riportare in coordinate reali (`nuvola-poc.html`, `_q`), e
   `Number.isFinite(+null)` risponde **true** perché `+null` fa 0. Effetto
   misurato prima della correzione: il verbale che va all'ente stampava «quota
   di base 0,00 m» e un ritaglio «X da 0,00 a 0,00, Y da 0,00 a 0,00, Z da 0,00
   a 0,00» — cioè una misura e una scatola di volume nullo, plausibili e false —
   e nello stesso momento l'elenco di ciò che non risulta registrato NON le
   nominava, perché usava la stessa guardia rovesciata. Le due bugie si
   coprivano a vicenda: chi leggeva vedeva parametri completi. */
test("⛔ quotaBase a null NON diventa «quota di base 0,00 m»", () => {
  const f = terra.descriviOrigine({ origine: { da: "visore", file: "volo.laz",
    cella: 0.5, quotaBase: null, areaCoperta: 729, ritaglio: null } });
  ok(!/quota di base 0,00/.test(f), "il numero inventato non c'è più: " + f.slice(0, 260));
  ok(/non risulta registrato/i.test(f) && /la quota di base/.test(f),
    "e viene dichiarata fra le mancanti: " + f.slice(-180));
  /* ⚠️ la prova non è «non stampa nulla»: gli altri parametri, che ci sono,
     devono restare — se no la correzione avrebbe tolto informazione vera */
  ok(/lato cella 0,50 m/.test(f) && /area coperta 729 m²/.test(f), "e quelli veri restano");
});
test("⛔ una quota di base pari a ZERO è una misura, e si scrive", () => {
  /* il contrario della prova qui sopra, ed è la ragione per cui la guardia NON
     può essere `> 0` come quella del lato cella: un piano di base a quota 0
     esiste, e una cava sotto il livello del mare ha quote negative */
  const zero = terra.descriviOrigine({ origine: { da: "visore", cella: 0.5, quotaBase: 0 } });
  ok(/quota di base 0,00 m/.test(zero), "quota 0 misurata: si scrive");
  ok(!/la quota di base/.test(zero.split("non risulta registrato")[1] || ""),
    "e non finisce fra le mancanti");
  const neg = terra.descriviOrigine({ origine: { da: "visore", cella: 0.5, quotaBase: -2.85 } });
  ok(/quota di base -2,85 m/.test(neg), "e una quota negativa pure: " + neg.slice(0, 200));
});
test("⛔ un ritaglio coi sei lati a null NON diventa una scatola da 0×0×0", () => {
  const f = terra.descriviOrigine({ origine: { da: "visore", cella: 0.5, quotaBase: 340.12,
    ritaglio: { x0: null, x1: null, y0: null, y1: null, z0: null, z1: null } } });
  ok(!/X da 0,00 a 0,00/.test(f), "la scatola falsa non si stampa: " + f.slice(0, 260));
  ok(/registrati ma non leggibili/.test(f),
    "⛔ e la differenza si dice: il ritaglio C'È, sono i suoi limiti a non leggersi");
  /* un ritaglio a metà è comunque inservibile: basta UN lato illeggibile */
  const meta = terra.descriviOrigine({ origine: { da: "visore", cella: 0.5, quotaBase: 1,
    ritaglio: { x0: 10, x1: 70, y0: 5, y1: 65, z0: 338, z1: null } } });
  ok(!/Ritaglio: X da/.test(meta), "un solo lato mancante e il ritaglio non si scrive");
  ok(/registrati ma non leggibili/.test(meta), "e viene dichiarato");
  /* ⚠️ «assente» e «illeggibile» restano due frasi diverse */
  const senza = terra.descriviOrigine({ origine: { da: "visore", cella: 0.5, quotaBase: 1 } });
  ok(/il ritaglio/.test(senza) && !/registrati ma non leggibili/.test(senza),
    "se il ritaglio non c'è proprio, si dice così: " + senza.slice(-140));
});
test("⛔ i valori che «sembrano numeri» non passano la guardia", () => {
  /* provati in scratchpad prima di scrivere il predicato: sono i due che il
     controllo ingenuo (`Number.isFinite(+v)` con la sola guardia su null e
     stringa vuota) lasciava passare — `+[5]` fa 5, `+true` fa 1 */
  for (const v of [true, [5], [], {}, "", "   ", "abc", NaN, Infinity]) {
    const f = terra.descriviOrigine({ origine: { da: "visore", cella: 0.5, quotaBase: v } });
    ok(!/quota di base/.test(f.split("non risulta registrato")[0]),
      "quotaBase = " + JSON.stringify(v) + " non è una quota: " + f.slice(0, 200));
  }
});
console.log("\n— Scudo: gli indici infortunistici (IF, IG, LTIFR) —");
/* ⛔ La prova che regge l'unità: SENZA LE ORE l'indice non si calcola. Il
   travestimento pericoloso qui è un indice BASSO — la notizia migliore che
   un'azienda possa leggere sulla propria sicurezza — ottenuto stimando le ore
   dal numero di operatori. */
const INF = [
  { data: "2026-02-03", tipo: "infortunio", giorniAssenza: 4 },
  { data: "2026-05-18", tipo: "near-miss", giorniAssenza: 0 },
  { data: "2026-06-01", tipo: "infortunio", giorniAssenza: 0 },
  { data: "2025-04-04", tipo: "infortunio", giorniAssenza: 30 },
];
test("⛔ senza le ore lavorate i tre indici NON si calcolano, e la funzione dice perché", () => {
  for (const ore of [null, undefined, 0, "", NaN, -100]) {
    const r = scudo.indiciInfortunistici(INF, ore, 2026);
    eq(r.calcolabile, false, "su ore=" + JSON.stringify(ore));
    eq([r.indiceFrequenza, r.indiceGravita, r.ltifr], [null, null, null], "nessun numero inventato");
    ok(/ORE LAVORATE/.test(r.motivo), "e la ragione è scritta");
    ok(/denominatore inventato|più basso del vero/.test(r.motivo), "col perché non si stima");
  }
});
test("i conteggi ci sono comunque: quelli non dipendono dalle ore", () => {
  const r = scudo.indiciInfortunistici(INF, null, 2026);
  eq(r.infortuni, 2, "infortuni dell'anno (i near-miss non sono infortuni)");
  eq(r.conAssenza, 1, "di cui con assenza");
  eq(r.giornatePerse, 4, "giornate perse");
  eq(r.oreLavorate, null, "e le ore restano dichiarate assenti");
});
test("con le ore i tre indici escono, e con le formule del settore", () => {
  const r = scudo.indiciInfortunistici(INF, 100000, 2026);
  eq(r.calcolabile, true, "si calcola");
  eq(r.indiceFrequenza, 20, "IF = 2 × 1.000.000 / 100.000");
  eq(r.indiceGravita, 0.04, "IG = 4 × 1.000 / 100.000");
  eq(r.ltifr, 10, "LTIFR = 1 × 1.000.000 / 100.000 (solo quelli con assenza)");
});
test("l'anno separa davvero: il 2025 non entra nel 2026", () => {
  eq(scudo.indiciInfortunistici(INF, 100000, 2025).giornatePerse, 30, "il 2025 ha le sue 30");
  eq(scudo.indiciInfortunistici(INF, 100000, 2026).giornatePerse, 4, "il 2026 le sue 4");
});
test("un anno senza infortuni dà indici a ZERO, che è un fatto — non l'assenza di dati", () => {
  const r = scudo.indiciInfortunistici(INF, 100000, 2024);
  eq(r.calcolabile, true, "le ore ci sono, quindi si calcola");
  eq([r.indiceFrequenza, r.indiceGravita, r.ltifr], [0, 0, 0], "zero infortuni = indici zero");
  eq(r.infortuni, 0, "ed è dichiarato che sono zero");
});

// ── Scudo · andamento indici ────────────────────────────────────────────────
console.log("\n— Scudo: l'andamento degli indici anno per anno —");
/* Tre difetti che questa unità ha avuto davvero, trovati in scratchpad prima di
   scrivere la funzione nel modulo, e che queste prove tengono chiusi:
   A. il messaggio «un anno solo con le ore» MENTIVA quando un anno con le ore
      cadeva fuori dal periodo mostrato;
   C. due registrazioni di ore diverse per lo stesso anno vincevano l'ultima in
      silenzio, cioè cambiavano l'indice senza che si vedesse;
   E. l'anno si leggeva in modo più severo che in `indiciInfortunistici`, quindi
      un infortunio con `data:"2026"` entrava nell'indice ma non nella serie. */
const INF_TREND = [
  { data: "2024-03-01", tipo: "infortunio", giorniAssenza: 10 },
  { data: "2024-09-01", tipo: "infortunio", giorniAssenza: 0 },
  { data: "2025-04-04", tipo: "infortunio", giorniAssenza: 30 },
  { data: "2026-02-03", tipo: "infortunio", giorniAssenza: 4 },
  { data: "2026-05-18", tipo: "near-miss", giorniAssenza: 0 },
];
const ORE_TREND = [{ anno: 2024, ore: 100000 }, { anno: 2025, ore: 100000 }, { anno: 2026, ore: 100000 }];
test("INDICI_TREND è l'elenco dei tre indici, nell'ordine in cui si leggono", () => {
  eq(scudo.INDICI_TREND.map(d => d.sigla), ["IF", "IG", "LTIFR"], "frequenza, gravità, LTIFR");
  eq(scudo.INDICI_TREND.map(d => d.chiave), ["indiceFrequenza", "indiceGravita", "ltifr"],
    "e le chiavi sono quelle che indiciInfortunistici restituisce davvero");
  const r = scudo.indiciInfortunistici([{ data: "2026-01-01", tipo: "infortunio", giorniAssenza: 1 }], 100000, 2026);
  ok(scudo.INDICI_TREND.every(d => d.chiave in r), "nessuna chiave inventata: se una sparisse, l'andamento leggerebbe undefined");
  ok(scudo.INDICI_TREND.every(d => d.nome && d.sigla), "ognuno porta il nome esteso e la sigla");
});
test("la serie esce un anno per riga, dal primo anno noto all'anno chiesto", () => {
  const r = scudo.andamentoIndici(INF_TREND, ORE_TREND, { annoFine: 2026 });
  eq(r.anni.map(x => x.anno), [2024, 2025, 2026], "2024, 2025, 2026");
  eq(r.misurabili, 3, "tutti e tre misurabili");
  eq(r.anni.map(x => x.indiceFrequenza), [20, 10, 10], "IF anno per anno");
  eq([r.dal, r.al], [2024, 2026], "il periodo mostrato è dichiarato");
});
test("⛔ un anno SENZA ore è un buco, non uno zero", () => {
  const r = scudo.andamentoIndici(INF_TREND, [{ anno: 2024, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq(r.anni[1].anno, 2025, "il 2025 resta in serie: non sparisce");
  eq(r.anni[1].calcolabile, false, "e si dichiara non calcolabile");
  eq([r.anni[1].indiceFrequenza, r.anni[1].indiceGravita, r.anni[1].ltifr], [null, null, null],
    "null — che il motore dei grafici non scavalca; 0 avrebbe disegnato un anno perfetto");
  ok(/ORE LAVORATE/.test(r.anni[1].motivo), "con la ragione scritta");
});
test("⛔ un anno con INFORTUNI ma senza ore viene detto per nome", () => {
  const r = scudo.andamentoIndici(INF_TREND, [{ anno: 2024, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq(r.conEventiSenzaOre, [2025], "è il buco che nasconde una notizia brutta");
  const s = scudo.andamentoIndici([{ data: "2026-01-01", tipo: "infortunio", giorniAssenza: 1 }],
    [{ anno: 2025, ore: 100000 }], { annoFine: 2026 });
  eq(s.conEventiSenzaOre, [2026], "e vale anche per l'anno in corso");
});
test("il confronto è fra gli ultimi due anni MISURATI, e dice se sono consecutivi", () => {
  const r = scudo.andamentoIndici(INF_TREND, ORE_TREND, { annoFine: 2026 });
  eq([r.confronto.da, r.confronto.a], [2025, 2026], "2025 → 2026");
  eq(r.confronto.adiacenti, true, "consecutivi");
  const s = scudo.andamentoIndici(INF_TREND, [{ anno: 2024, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq([s.confronto.da, s.confronto.a], [2024, 2026], "saltando il buco");
  eq(s.confronto.adiacenti, false, "e NON sono consecutivi: la pagina non può dire «l'anno scorso»");
  eq(s.confronto.salto, 2, "quanti anni di distanza");
});
test("⛔ su questi indici SCENDERE è migliorare, e il verso lo dice la funzione", () => {
  const r = scudo.andamentoIndici(INF_TREND, ORE_TREND, { annoFine: 2026 });
  const per = Object.fromEntries(r.confronto.per.map(p => [p.sigla, p]));
  eq(per.IG.da, 0.3, "IG 2025 = 30 giornate × 1.000 / 100.000");
  eq(per.IG.a, 0.04, "IG 2026 = 4 giornate × 1.000 / 100.000");
  eq(per.IG.verso, "migliora", "scende = migliora, non «−86,7% in rosso»");
  eq(per.IG.variazione, -86.7, "la variazione è negativa proprio quando la notizia è buona");
  eq(per.IF.verso, "stabile", "IF 10 → 10");
  eq(r.confronto.verso, "migliora", "verso complessivo");
});
test("⛔ meno infortuni ma più gravi non si riassume in una freccia: è «misto»", () => {
  const inf = [
    { data: "2025-01-01", tipo: "infortunio", giorniAssenza: 1 },
    { data: "2025-02-01", tipo: "infortunio", giorniAssenza: 1 },
    { data: "2026-01-01", tipo: "infortunio", giorniAssenza: 60 },
  ];
  const r = scudo.andamentoIndici(inf, [{ anno: 2025, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  const per = Object.fromEntries(r.confronto.per.map(p => [p.sigla, p]));
  eq(per.IF.verso, "migliora", "2 infortuni → 1");
  eq(per.IG.verso, "peggiora", "2 giornate perse → 60");
  eq(r.confronto.verso, "misto", "e il riassunto non sceglie quale delle due raccontare");
});
test("⛔ da zero non esiste una variazione in percentuale", () => {
  const r = scudo.andamentoIndici([{ data: "2026-02-03", tipo: "infortunio", giorniAssenza: 4 }],
    [{ anno: 2025, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  const p = r.confronto.per[0];
  eq(p.da, 0, "il 2025 era a zero");
  /* ⚠️ IDENTITÀ, NON `eq`. `eq` confronta con JSON.stringify, e
     `JSON.stringify(Infinity)` vale `"null"`: scritta `eq(p.variazione, null)`
     questa riga passava ANCHE con la divisione per zero rimessa dentro, cioè
     proprio sul difetto che porta nel nome. L'ha trovata la controprova. */
  ok(p.variazione === null, "niente Infinity travestito da null");
  ok(!Number.isFinite(p.variazione), "e nessun numero al suo posto");
  ok(/zero/.test(p.variazionePerche), "e la ragione è scritta");
  eq(p.verso, "peggiora", "ma il verso si sa lo stesso");
  eq(p.delta, 10, "e il salto in valore pure");
});
test("⛔ due registrazioni di ore DIVERSE per lo stesso anno non si risolvono a caso", () => {
  const r = scudo.andamentoIndici([{ data: "2026-01-01", tipo: "infortunio", giorniAssenza: 2 }],
    [{ anno: 2026, ore: 100000 }, { anno: 2026, ore: 50000 }], { annoFine: 2026 });
  const u = r.anni[r.anni.length - 1];
  eq(u.calcolabile, false, "l'anno doppio non è calcolabile");
  ok(/DUE registrazioni/.test(u.motivo), "e la ragione lo dice");
  eq(r.anniDubbi, [2026], "l'anno è elencato fra i dubbi");
  const s = scudo.andamentoIndici([], [{ anno: 2026, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq(s.anni[s.anni.length - 1].calcolabile, true, "ma due registrazioni UGUALI non sono un dubbio");
});
test("⛔ il messaggio «un anno solo» non mente su chi sta fuori dal periodo", () => {
  const r = scudo.andamentoIndici([], [{ anno: 2015, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq(r.confronto.confrontabile, false, "nel periodo mostrato ce n'è uno solo");
  eq(r.oreFuoriPeriodo, [2015], "ma il 2015 ha le ore ed è fuori: dichiarato");
  ok(/2015/.test(r.confronto.motivo), "e il messaggio lo nomina, invece di far credere che non esista");
  ok(r.anni.length <= 6, "la finestra non stampa dodici anni vuoti");
});
test("senza nessun anno misurabile non si inventa un andamento", () => {
  const r = scudo.andamentoIndici(INF_TREND, [], { annoFine: 2026 });
  eq(r.misurabili, 0, "nessun anno con le ore");
  eq(r.confronto.confrontabile, false, "quindi niente andamento");
  ok(/non c'è nessun anno con le ore/.test(r.confronto.motivo), "e la ragione è scritta");
  eq(r.anni.length, 3, "la serie però c'è, tutta a buchi");
  ok(r.anni.every(x => x.calcolabile === false), "e nessun anno finge di valere zero");
});
test("⛔ pochi eventi = nessuna tendenza, con la SOGLIA di riepilogoNearMiss", () => {
  const r = scudo.andamentoIndici(INF_TREND, ORE_TREND, { annoFine: 2026 });
  eq(r.confronto.eventi, 2, "1 infortunio nel 2025 + 1 nel 2026");
  eq(r.confronto.pochi, true, "due eventi non sono una tendenza");
  eq(r.confronto.pochi, scudo.troppoPochiPerTendenza(r.confronto.eventi),
    "e la soglia è LA STESSA, non una seconda copia");
  const tanti = [];
  for (let i = 0; i < 4; i++) tanti.push({ data: "2025-0" + (i + 1) + "-01", tipo: "infortunio", giorniAssenza: 1 });
  for (let i = 0; i < 4; i++) tanti.push({ data: "2026-0" + (i + 1) + "-01", tipo: "infortunio", giorniAssenza: 1 });
  const s = scudo.andamentoIndici(tanti, [{ anno: 2025, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq(s.confronto.eventi, 8, "otto eventi");
  eq(s.confronto.pochi, false, "sopra la soglia la tendenza si può leggere");
});
test("⛔ l'anno si legge come lo legge indiciInfortunistici, non più severo", () => {
  const r = scudo.andamentoIndici([{ data: "2024", tipo: "infortunio", giorniAssenza: 3 }],
    [{ anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq(r.anni[0].anno, 2024, "una data ridotta al solo anno fa comparire il 2024 nella serie");
  eq(r.anni[0].infortuni, 1, "con il suo infortunio dentro");
  eq(scudo.indiciInfortunistici([{ data: "2024", tipo: "infortunio", giorniAssenza: 3 }], 100000, 2024).infortuni, 1,
    "che è esattamente quello che conta indiciInfortunistici");
});
test("i near-miss non entrano negli indici, nemmeno nell'andamento", () => {
  const soloNm = [{ data: "2025-01-01", tipo: "near-miss", giorniAssenza: 0 },
                  { data: "2026-01-01", tipo: "near-miss", giorniAssenza: 0 }];
  const r = scudo.andamentoIndici(soloNm, [{ anno: 2025, ore: 100000 }, { anno: 2026, ore: 100000 }], { annoFine: 2026 });
  eq(r.anni.map(x => x.indiceFrequenza), [0, 0], "IF resta zero: un near-miss non è un infortunio");
  eq(r.confronto.verso, "stabile", "e l'andamento è piatto, non «migliora»");
});
