/* ⛔ L'IDENTITÀ, non il comportamento: due copie uguali oggi divergono domani
   senza che nessuno lo veda. È la regola del `shared/` scritta in CLAUDE.md. */
/* ⛔ IL PERCORSO PUNTATO ANCHE NELLA DIMOSTRAZIONE (misura 5b, 08/08).
   Senza questa funzione la cura contro la perdita silenziosa funzionerebbe
   **solo col database vero**: il livello in memoria fa `Object.assign`, e
   `Object.assign` di una chiave `"esiti.dpi"` crea una proprietà **letterale
   col punto dentro** — nessun errore, e la spunta non si vede. Cioè la
   correzione avrebbe rotto la DIMOSTRAZIONE, che è quello che il fondatore
   mostra, mentre i dati veri andavano bene. */
test("applicaPercorsi: un percorso puntato tocca il singolo campo, come fa Firestore", () => {
  eq(ponti.applicaPercorsi({ esiti: { dpi: false, luci: false } }, { "esiti.dpi": true }),
     { esiti: { dpi: true, luci: false } }, "cambia una voce e lascia stare l'altra");
  eq(ponti.applicaPercorsi({ a: 1 }, { b: 2 }), { a: 1, b: 2 }, "un campo senza punto resta un campo");
  eq(ponti.applicaPercorsi({ esiti: { a: false } }, { "esiti.a": true, ora: "08:00" }),
     { esiti: { a: true }, ora: "08:00" }, "puntati e piani insieme");
  eq(ponti.applicaPercorsi({}, { "a.b.c": 1 }), { a: { b: { c: 1 } } }, "due livelli di profondità");
  /* i rami che non sono un oggetto si aprono, come fa Firestore: capita
     davvero su una riga vecchia che quel campo non l'aveva */
  for (const [che, v] of [["assente", undefined], ["null", null], ["scalare", 5], ["array", [1, 2]]])
    eq(ponti.applicaPercorsi(v === undefined ? {} : { esiti: v }, { "esiti.dpi": true }),
       { esiti: { dpi: true } }, `ramo ${che}`);
  eq(ponti.applicaPercorsi({ esiti: { a: 1 } }, { "esiti.a": null }), { esiti: { a: null } },
     "⛔ e un null DICHIARATO si scrive: è la convenzione «non si può calcolare», non un'assenza");
  eq(ponti.applicaPercorsi({ a: 1 }, null), { a: 1 }, "niente da applicare non rompe");
  /* ⛔ la controprova, dentro la prova: quello che faceva prima */
  const ingenuo = Object.assign({ esiti: { dpi: false } }, { "esiti.dpi": true });
  eq(ingenuo.esiti.dpi, false, "con Object.assign la spunta NON arriva…");
  eq(ingenuo["esiti.dpi"], true, "…perché la chiave resta letterale, col punto dentro");
});
/* ⛔ E IL GIRO VERO, ATTRAVERSO IL LIVELLO DATI DELL'APP — non contro la
   funzione condivisa, che potrebbe essere giusta e non arrivare mai lì.
   ⚠️ È `await test(...)`, non `test(...)`: una prova asincrona **lasciata in
   volo** in fondo al file verrebbe messa in coda dopo `await Promise.all` e il
   totale si stamperebbe senza aspettarla (misurato il 07/08: 1842 prima e 1842
   dopo). `test` restituisce la sua promessa apposta, e qui si aspetta. */
await test("⛔ il giro vero: due spunte diverse sulla stessa checklist convivono nella DIMOSTRAZIONE", async () => {
  const db = await campo.campoData();
  eq(db.mode, "demo", "senza login il livello dati è quello della dimostrazione");
  const { id } = await db.aggiungi("checklist",
    { data: "2026-08-08", turno: "mattina", esiti: { dpi: false, luci: false } });
  const riga = async () => (await db.checklist()).find((r) => r.id === id);
  /* Anna spunta i DPI, Bruno le luci: due scritture separate, come due telefoni */
  await db.aggiorna("checklist", id, { "esiti.dpi": true });
  await db.aggiorna("checklist", id, { "esiti.luci": true });
  const dopo = await riga();
  eq(dopo.esiti, { dpi: true, luci: true }, "convivono: nessuna delle due si perde");
  eq(Object.keys(dopo).filter((k) => k.includes(".")), [],
    "e non è rimasta nessuna chiave letterale col punto dentro");
  await db.aggiorna("checklist", id, { "esiti.dpi": ponti.DW_CANCELLA });
  eq((await riga()).esiti, { luci: true }, "e il contrassegno toglie la voce davvero");
});
await test("⛔ il giro vero: `trasforma` esiste sulle DUE strade e la dimostrazione lo usa", async () => {
  /* la guardia collegata, versione elenchi: la funzione condivisa può essere
     giusta e non arrivare mai al livello dati. Qui si passa dal db vero
     dell'app, in modo dimostrazione. */
  const db = await sentinella.sentinellaData();
  eq(db.mode, "demo", "senza login il livello dati è quello della dimostrazione");
  ok(typeof db.trasforma === "function", "la dimostrazione espone `trasforma`");
  /* e la seconda app che ne ha bisogno: se domani se ne aggiunge una terza,
     questa riga dice subito che le manca invece di lasciarlo scoprire a mano */
  const dbS = await scudo.scudoData();
  ok(typeof dbS.trasforma === "function", "anche la dimostrazione di Scudo espone `trasforma`");
  const { id } = await db.aggiungi("monitoraggi", { nome: "P1", letture: [{ data: "2026-01-01", valore: 1 }] });
  const riga = async () => (await db.monitoraggi()).find((m) => m.id === id);
  await db.trasforma("monitoraggi", id, (m) => ({ letture: [...m.letture, { data: "2026-01-02", valore: 2 }] }));
  eq((await riga()).letture.map((l) => l.valore), [1, 2], "la lettura si aggiunge a quelle VERE del momento");
  await db.trasforma("monitoraggi", id, () => null);
  eq((await riga()).letture.length, 2, "«niente da fare» non tocca niente");
  /* e la riga che non c'è più dice la stessa frase dell'altra strada */
  let msg = "";
  try { await db.trasforma("monitoraggi", "mai-esistito", () => ({ x: 1 })); } catch (e) { msg = e.message; }
  ok(/non c'è più/.test(msg), `una riga inesistente va detta: ${msg}`);
});
await test("trasformaAtomico: rilegge DENTRO la transazione, e non resuscita una riga tolta", async () => {
  /* con dei finti: il soggetto è il CONTRATTO (rileggo, decido, scrivo una
     volta), non Firestore — quello lo prova la misura sotto l'emulatore */
  const finto = (dati) => {
    const scritte = [];
    const rif = { firestore: "db-finto" };
    const runTransaction = async (_db, corpo) => corpo({
      get: async () => ({ exists: () => dati !== null, data: () => dati }),
      update: (_r, c) => scritte.push(c),
    });
    return { rif, runTransaction, deleteField: () => "<<del>>", scritte };
  };
  const a = finto({ letture: [{ v: 1 }] });
  await ponti.trasformaAtomico(a, (m) => ({ letture: [...m.letture, { v: 2 }] }));
  eq(a.scritte, [{ letture: [{ v: 1 }, { v: 2 }] }], "decide sulla lettura fatta DENTRO, e scrive una volta sola");
  const b = finto({ letture: [] });
  await ponti.trasformaAtomico(b, () => null);
  eq(b.scritte, [], "⛔ «niente da fare» non scrive: una scrittura a vuoto è comunque un giro perso");
  const c = finto({ x: 1 });
  await ponti.trasformaAtomico(c, () => ({ x: ponti.DW_CANCELLA }));
  eq(c.scritte, [{ x: "<<del>>" }], "e il contrassegno passa dalla traduzione");
  /* la riga tolta nel frattempo: non si ricrea di nascosto */
  let msg = "";
  try { await ponti.trasformaAtomico(finto(null), () => ({ x: 1 })); } catch (e) { msg = e.message; }
  ok(/non c'è più/.test(msg), `una riga cancellata va detta, non ricreata: ${msg}`);
});
test("trasformaInMemoria: stesso contratto della strada vera", () => {
  /* ⛔ se i due contratti divergono, la dimostrazione smette di dimostrare */
  const riga = { letture: [{ v: 1 }] };
  ponti.trasformaInMemoria(riga, (m) => ({ letture: [...m.letture, { v: 2 }] }));
  eq(riga.letture, [{ v: 1 }, { v: 2 }], "aggiunge davvero");
  const ferma = { a: 1 };
  ponti.trasformaInMemoria(ferma, () => null);
  eq(ferma, { a: 1 }, "«niente da fare» non tocca niente");
  const conPercorso = { esiti: { a: false } };
  ponti.trasformaInMemoria(conPercorso, () => ({ "esiti.a": true }));
  eq(conPercorso, { esiti: { a: true } }, "e capisce anche i percorsi puntati");
  let msg = "";
  try { ponti.trasformaInMemoria(undefined, () => ({ x: 1 })); } catch (e) { msg = e.message; }
  ok(/non c'è più/.test(msg), "e dice la STESSA frase dell'altra strada");
  /* la funzione riceve una COPIA: chi la scrive non può cambiare la riga di
     nascosto e far credere che l'abbia fatto la transazione */
  const orig = { a: 1 };
  ponti.trasformaInMemoria(orig, (m) => { m.a = 99; return null; });
  eq(orig, { a: 1 }, "quello che arriva alla funzione è una copia");
});
test("⛔ nessun campo COMPOSITO torna a essere scritto intero da un aggiornamento", () => {
  /* Il censimento della misura 5b, reso una regola: erano DODICI punti in cui
     una lista veniva letta, cambiata in un punto e riscritta intera — e due
     persone che toccavano voci diverse si cancellavano a vicenda in silenzio.
     Undici sono passati al percorso puntato o alla transazione; qui si
     pretende che non ne rinasca uno. */
  const CAMPI = [["campo", "esiti"], ["scudo", "azioniId"], ["scudo", "esiti"],
                 ["scudo", "misure"], ["sentinella", "tarature"], ["sentinella", "letture"]];
  const tornati = [];
  for (const [app, campo] of CAMPI) {
    const src = readFileSync(join(HERE, `../../${app}/index.html`), "utf8");
    /* ⚠️ il RIPIEGO dichiarato non è una violazione: quando una voce ha un
       punto nel nome `percorsiDi` risponde `null` e si riscrive l'oggetto
       intero, di proposito. Si guarda quindi il contorno della chiamata: se
       cita `percorsiDi`, è il ripiego; se no, è una scrittura intera vera. */
    for (const m of src.matchAll(new RegExp(`db\\.aggiorna\\([^)]*\\b${campo}\\b`, "g"))) {
      const intorno = src.slice(Math.max(0, m.index - 400), m.index + 200);
      if (!/percorsiDi\(/.test(intorno)) { tornati.push(`${app}.${campo}`); break; }
    }
  }
  eq(tornati, [], "questi campi compositi sono tornati a essere riscritti interi");
  eq(CAMPI.length, 6, "e ha guardato tutti e sei i campi del censimento");
  /* ⛔ `atmosfera` NON è in elenco, e la ragione va scritta invece che
     lasciata intuire: lì l'utente invia TUTTE le misure di gas insieme, quindi
     non è la spunta persa — è un conflitto sullo stesso campo (caso 2 della
     misura), e la risposta a quello non è tecnica. */
  const perm = readFileSync(join(HERE, "../../scudo/index.html"), "utf8");
  ok(/db\.aggiorna\("permessi", p\.id, \{ atmosfera/.test(perm),
    "e `atmosfera` resta scritta intera di proposito: se un giorno cambiasse, questa riga va rivista");
});
test("⛔ descriviResponsabile: «da assegnare» e «non riesco a leggere chi è» sono due cose diverse", () => {
  /* Il filo della settimana, su un'etichetta invece che su un numero. Il
     responsabile di un'azione correttiva si ricava cercando il suo id
     nell'elenco che arriva DA SCUDO: se quella lettura fallisce l'elenco
     arriva vuoto, e un'azione CHE IL RESPONSABILE CE L'HA veniva mostrata come
     «responsabile da assegnare» — un'affermazione sull'azione, mentre il fatto
     riguarda la nostra lettura. Chi legge quella riga pensa che nessuno se ne
     stia occupando, e magari la riassegna. */
  const con = { responsabileId: "l1" };
  eq(sentinella.descriviResponsabile(con, [{ id: "l1", nome: "Mario Rossi" }], true),
     { testo: "responsabile Mario Rossi", noto: true }, "il nome si legge e si dice");
  eq(sentinella.descriviResponsabile(con, [], false).noto, false,
     "elenco NON leggibile: la frase si dichiara non nota");
  ok(/non si legge da Scudo/.test(sentinella.descriviResponsabile(con, [], false).testo),
     "e dice CHE NON SI SA, non che non c'è");
  eq(sentinella.descriviResponsabile(con, [], true),
     { testo: "responsabile non più in anagrafica", noto: true },
     "letto davvero e non trovato: è un fatto, e non è «da assegnare»");
  eq(sentinella.descriviResponsabile({}, [], true),
     { testo: "responsabile da assegnare", noto: true }, "senza id, «da assegnare» è VERO");
  eq(sentinella.descriviResponsabile(null, null, true).testo, "responsabile da assegnare",
     "e il niente non rompe");
  /* ⛔ la prova che separa i due stati che prima erano identici */
  ok(sentinella.descriviResponsabile(con, [], false).testo
     !== sentinella.descriviResponsabile({}, [], true).testo,
     "⛔ le due frasi che prima erano la stessa adesso sono diverse");
  /* la riga c'è ma il nome è vuoto: non è «non più in anagrafica» — c'è.
     ⚠️ Caso NON raggiungibile dai percorsi del prodotto (vedi il commento di
     `statoResponsabile`): sta qui perché il disegno non menta, non perché
     capiti. */
  eq(sentinella.descriviResponsabile(con, [{ id: "l1", nome: "" }], true).testo,
     "responsabile assegnato, in anagrafica non ha un nome",
     "in anagrafica senza nome: si dice quello, non «non c'è più»");
});
test("⛔ statoResponsabile: la DECISIONE è una sola, e le due app la chiamano", () => {
  /* La regola del `shared/`: una regola che serve a due app vive lì e non si
     riscrive. Qui non si pretende l'identità delle FRASI — sono diverse
     apposta, e Sentinella nomina Scudo perché lo legge da fuori — ma che
     nessuna delle due decida per conto suo. La prova che lo mostra: uno stato
     che le due app scrivono con parole diverse partendo dallo stesso caso. */
  const con = { responsabileId: "l1" }, LAV = [{ id: "l1", nome: "Mario Rossi" }];
  eq(ponti.statoResponsabile(con, LAV), { stato: "trovato", nome: "Mario Rossi", noto: true },
     "id e nome: trovato");
  eq(ponti.statoResponsabile(con, []), { stato: "fuori-anagrafica", nome: "", noto: true },
     "elenco leggibile e nessuno: fuori anagrafica");
  eq(ponti.statoResponsabile(con, [], false), { stato: "illeggibile", nome: "", noto: false },
     "elenco NON leggibile: è un non-so, e si dichiara");
  eq(ponti.statoResponsabile({}, LAV), { stato: "assente", nome: "", noto: true },
     "nessun id: assente");
  eq(ponti.statoResponsabile(con, [{ id: "l1", nome: "" }]), { stato: "senza-nome", nome: "", noto: true },
     "la riga c'è e il nome no: è un terzo caso");
  eq(ponti.statoResponsabile(null, null).stato, "assente", "e il niente non rompe");
  /* ⛔ LO STESSO CASO, LE DUE APP: stessa decisione, due frasi. */
  const fuori = { responsabileId: "l9" };
  eq(ponti.statoResponsabile(fuori, LAV).stato, "fuori-anagrafica", "la decisione");
  eq(sentinella.descriviResponsabile(fuori, LAV).testo, "responsabile non più in anagrafica",
     "come la scrive Sentinella");
  eq(scudo.etichettaResponsabile(fuori, LAV).testo, "responsabile non più in anagrafica",
     "come la scrive Scudo sullo schermo");
  eq(scudo.etichettaResponsabile(fuori, LAV).nome, "non più in anagrafica",
     "e nel CSV, senza il prefisso «resp.»");
});
test("⛔ Scudo: lo schermo e il CSV dicono la STESSA cosa sul responsabile", () => {
  /* La domanda di CLAUDE.md — *dove questa app compone qualcosa che ESCE, chi
     decide i suoi numeri?* — qui rispondeva NO in tre posti: la lista faceva
     `byId[...]`, l'export teneva la sua copia, e lo scadenzario una terza. Tutte
     e tre dicevano «da assegnare» a un id che punta a chi non è più in
     anagrafica: cioè il foglio che va all'ispettore diceva che di
     quell'azione non si occupa nessuno mentre un responsabile era stato scelto. */
  const LAV = [{ id: "d3", nome: "Mario Rossi" }];
  eq(scudo.etichettaResponsabile({ responsabileId: "d3" }, LAV),
     { testo: "resp. Mario Rossi", nome: "Mario Rossi", stato: "trovato", noto: true },
     "trovato: «resp.» a schermo, il nome nudo nel file");
  eq(scudo.etichettaResponsabile({ responsabileId: null }, LAV),
     { testo: "responsabile da assegnare", nome: "da assegnare", stato: "assente", noto: true },
     "senza id, «da assegnare» è vero anche nel file");
  eq(scudo.etichettaResponsabile({ responsabileId: "d9" }, LAV).nome, "non più in anagrafica",
     "⛔ e l'id che punta a nessuno NON è «da assegnare»");
  eq(scudo.etichettaResponsabile({ responsabileId: "dx" }, [{ id: "dx", nome: "" }]).nome,
     "senza nome in anagrafica", "e la riga senza nome non esce come cella vuota");
  /* ⛔ la prova che separa i due stati che prima erano la stessa cella */
  ok(scudo.etichettaResponsabile({ responsabileId: "d9" }, LAV).nome
     !== scudo.etichettaResponsabile({ responsabileId: null }, LAV).nome,
     "⛔ le due celle che prima erano identiche adesso sono diverse");
  /* e la cella non è mai vuota: in un foglio di conformità il vuoto si legge
     «non serve» — è la ragione scritta accanto all'export */
  for (const a of [{ responsabileId: null }, { responsabileId: "d9" }, { responsabileId: "d3" }, {}])
    ok(scudo.etichettaResponsabile(a, LAV).nome.length > 0, "nessuna cella vuota");
});
test("percorsiDi: costruisce i percorsi, e dice NO quando non si può", () => {
  eq(ponti.percorsiDi("esiti", { dpi: true, luci: false }),
     { "esiti.dpi": true, "esiti.luci": false }, "da voci a percorsi");
  eq(ponti.percorsiDi("esiti", {}), {}, "niente voci, niente percorsi");
  /* ⛔ la ragione per cui questa funzione esiste invece di due righe sul posto:
     una chiave che contiene GIÀ un punto verrebbe spezzata, e il dato finirebbe
     in un ramo che non esiste **senza nessun errore**. Si risponde `null` —
     la convenzione di casa per «non si può» — e chi chiama riscrive l'oggetto. */
  eq(ponti.percorsiDi("esiti", { "a.b": 1 }), null, "una voce col punto nel nome: non si può");
  eq(ponti.percorsiDi("esiti", { ok: 1, "a.b": 2 }), null, "e basta UNA a far rispondere no");
});
test("DW_CANCELLA: togliere una voce col percorso puntato, sulle due strade", () => {
  /* col database vero la cancellazione è `deleteField()`, in memoria è `delete`:
     la pagina scrive lo stesso contrassegno e non sa quale strada sta usando */
  const o = { esiti: { a: 1, b: 2 } };
  ponti.applicaPercorsi(o, { "esiti.a": ponti.DW_CANCELLA });
  eq(o, { esiti: { b: 2 } }, "in memoria la voce sparisce davvero");
  eq(ponti.applicaPercorsi({ x: 1, y: 2 }, { x: ponti.DW_CANCELLA }), { y: 2 },
     "e vale anche senza percorso puntato");
  eq(ponti.traduciCancellazioni({ a: ponti.DW_CANCELLA, b: 1 }, () => "<<del>>"),
     { a: "<<del>>", b: 1 }, "sulla strada di Firestore diventa deleteField(), il resto passa");
  eq(ponti.traduciCancellazioni(null, () => "<<del>>"), {}, "niente da tradurre non rompe");
  /* ⛔ è un oggetto CONGELATO e unico, non una stringa: una sentinella scritta
     come testo può collidere con un dato vero, e quella collisione non produce
     niente da leggere */
  ok(Object.isFrozen(ponti.DW_CANCELLA), "il contrassegno è congelato");
  eq(ponti.applicaPercorsi({ x: 1 }, { x: "__dwCancella__" }), { x: "__dwCancella__" },
     "una STRINGA che gli somiglia resta un dato, non diventa una cancellazione");
});
test("⛔ e le SEI dimostrazioni la usano davvero: una guardia scollegata non protegge niente", () => {
  /* La funzione può essere giusta e non essere chiamata da nessuno — è la
     famiglia del `<script>` dimenticato. Qui si guarda il livello in memoria
     di ognuna delle sei app: deve passare da `applicaPercorsi`, e NON deve
     essere rimasto l'`Object.assign` che tratta «esiti.dpi» come una chiave. */
  const APP = ["campo", "conti", "flotta", "scudo", "sentinella", "terra"];
  const senza = [], vecchie = [], senzaTrad = [];
  for (const a of APP) {
    const src = readFileSync(join(HERE, `../../${a}/${a}-data.js`), "utf8");
    if (!/applicaPercorsi\(x,\s*d(ata)?\)/.test(src)) senza.push(a);
    if (/Object\.assign\(x,\s*d(ata)?\)/.test(src)) vecchie.push(a);
    /* e la STRADA DI FIRESTORE: senza la traduzione, il contrassegno arriverebbe
       al database come un oggetto qualunque e verrebbe SCRITTO invece che
       cancellare — un dato finto al posto di una voce tolta */
    if (!/traduciCancellazioni\(d(ata)?,\s*deleteField\)/.test(src)) senzaTrad.push(a);
  }
  eq(senza, [], "queste dimostrazioni non applicano i percorsi puntati");
  eq(vecchie, [], "queste hanno ancora l'Object.assign che tratta «esiti.dpi» come una chiave");
  eq(senzaTrad, [], "queste non traducono il contrassegno di cancellazione per Firestore");
  eq(APP.length, 6, "e ha guardato tutte e sei le app");
});
test("applicaPercorsi è LA STESSA funzione in tutte e sei le app", () => {
  /* l'identità, non il comportamento: due copie uguali oggi divergono domani */
  for (const [nome, m] of [["campo", campo], ["conti", conti], ["flotta", flotta],
                           ["scudo", scudo], ["sentinella", sentinella], ["terra", terra]])
    ok(m.applicaPercorsi === undefined || m.applicaPercorsi === ponti.applicaPercorsi,
      `${nome} non deve tenersene una copia`);
});
